import argparse
import json
import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(raw):
    """Return a Decimal for raw, or None if it should be skipped."""
    if raw is None:
        return None
    s = str(raw).strip()
    if not s:
        return None
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    # remove currency symbols, thousands separators and inner spaces
    for ch in ("$", ",", " ", "\t", "\u00a0"):
        s = s.replace(ch, "")
    if s.startswith("+"):
        s = s[1:]
    if s.startswith("-"):
        negative = not negative
        s = s[1:]
    if not s:
        return None
    try:
        value = Decimal(s)
    except InvalidOperation:
        return None
    return -value if negative else value


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    total = Decimal("0")
    with open(path, "r", newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        field = None
        for name in (reader.fieldnames or []):
            if name is not None and name.strip().lower() == "amount":
                field = name
                break
        if field is not None:
            for row in reader:
                value = parse_amount(row.get(field))
                if value is not None:
                    total += value

    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if total == 0:
        total = Decimal("0.00")
    print(str(total))


main()

import argparse
import json
import csv
from decimal import Decimal, ROUND_HALF_UP


def clean(raw):
    """Return a Decimal for raw, or None if it should be skipped."""
    if raw is None:
        return None
    s = str(raw)
    for ch in "$,()\t\r\n\u00a0 ":
        s = s.replace(ch, "")
    if not s:
        return None
    neg = False
    if s[0] in "+-":
        neg = s[0] == "-"
        s = s[1:]
    if not s:
        return None
    try:
        value = Decimal(s)
    except Exception:
        return None
    return -value if neg else value


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    total = Decimal("0")
    with open(path, newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        key = None
        for name in (reader.fieldnames or []):
            if name is not None and name.strip().lower() == "amount":
                key = name
                break
        if key is not None:
            for row in reader:
                value = clean(row.get(key))
                if value is not None:
                    total += value

    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if total == 0:
        total = Decimal("0.00")
    print(str(total))


main()

import argparse
import json

START = "08:00:00"
END = "08:30:00"


def valid_ts(t):
    if len(t) != 8 or t[2] != ":" or t[5] != ":":
        return False
    return t[0:2].isdigit() and t[3:5].isdigit() and t[6:8].isdigit()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]
    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            fields = line.split()
            if len(fields) < 2:
                continue
            ts, level = fields[0], fields[1]
            if level != "ERROR":
                continue
            if not valid_ts(ts):
                continue
            if START <= ts < END:
                count += 1
    print(count)


main()

import argparse
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    opts = json.loads(args.payload)
    path = opts["path"]

    latest = {}  # user -> (ts, action)
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(rec, dict):
                continue
            if "user" not in rec or "ts" not in rec:
                continue
            user = rec["user"]
            ts = rec["ts"]
            action = rec.get("action")
            if user not in latest or ts > latest[user][0]:
                latest[user] = (ts, action)

    count = 0
    for _user, (_ts, action) in latest.items():
        if action == "logout":
            count += 1
    print(count)


main()

import argparse
import csv
import json
from datetime import date


def parse_date(text):
    text = (text or "").strip()
    if len(text) != 10:
        return None
    parts = text.split("-")
    if len(parts) != 3:
        return None
    y, m, d = parts
    if not (len(y) == 4 and len(m) == 2 and len(d) == 2):
        return None
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        return None
    try:
        return date(int(y), int(m), int(d))
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    dates = []
    with open(path, "r", newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            value = row.get("date")
            parsed = parse_date(value)
            if parsed is not None:
                dates.append(parsed)

    if len(dates) < 2:
        print(0)
        return

    print((max(dates) - min(dates)).days)


main()
